#include <bits/stdc++.h>
using namespace std;

const int MAXN = 510;
int nodes, edges, mod, C[MAXN][MAXN], f1_array[MAXN], f2_array[MAXN][MAXN], g1_array[MAXN], g2_array[MAXN][MAXN];

int main() {
    scanf("%d %d %d", &nodes, &edges, &mod);
    for (int i = 0; i <= nodes; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == 0) C[i][j] = 1;
            else C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
        }
    }
    f1_array[0] = 1;
    for (int i = 1; i <= nodes; i++) {
        f1_array[i] = 0;
        g1_array[i] = 0;
        for (int j = 1; j <= i; j++) {
            f1_array[i] = (f1_array[i] + (long long)f1_array[j - 1] * f1_array[i - j] % mod * C[i - 1][j - 1]) % mod;
            int temp = ((long long)f1_array[j - 1] * g1_array[i - j] + (long long)g1_array[j - 1] * f1_array[i - j]) % mod;
            temp = (temp * (i + 1)) % mod;
            g1_array[i] = (g1_array[i] + ((long long)f1_array[j - 1] * f1_array[i - j] % mod * (C[j][2] + C[i - j + 1][2]) + temp) % mod * C[i - 1][j - 1]) % mod;
        }
        f1_array[i] = (long long)(i + 1) * f1_array[i] % mod;
    }
    g2_array[0][0] = 1;
    for (int i = 1; i <= nodes; i++) {
        for (int j = 0; j <= min(i, edges); j++) {
            f2_array[i][j] = f2_array[i - 1][j];
            g2_array[i][j] = g2_array[i - 1][j];
            for (int k = 1; k <= j; k++) {
                long long temp_f = (i - k ? f2_array[i - k - 1][j - k] : 1);
                f2_array[i][j] = (f2_array[i][j] + temp_f * f1_array[k] % mod * C[j][k]) % mod;
                long long temp_g = (i - k ? f2_array[i - k - 1][j - k] : 1);
                long long g_part = ((long long)temp_g * g1_array[k] + (long long)(i - k ? g2_array[i - k - 1][j - k] : 0) * f1_array[k]) % mod;
                g2_array[i][j] = (g2_array[i][j] + g_part * C[j][k]) % mod;
            }
        }
    }
    printf("%d\n", g2_array[nodes][edges]);
    return 0;
}
